/**
 * Exemplar cards for the LIBRARY styles, embedded as small (~512px) JPEG data
 * URLs. When the user picks a library style, the exemplar goes to gpt-image as
 * the second (style) image — a real visual anchor transfers composition rhythm,
 * palette and typography far better than palette words alone.
 *
 * SERVER-ONLY: import this module only from server code (infographic-service) —
 * it is ~259KB of base64 and must never reach the client bundle.
 *
 * Regenerate: create a card per style with the app itself, downscale to 512px
 * JPEG q80, and rebuild this file (see scratchpad/build-ref-module.mjs history).
 */
export const STYLE_REF_IMAGES: Record<string, string> = {
  "marketplace-clean":
    "data:image/jpeg;base64,",
  "premium-dark":
    "data:image/jpeg;base64,",
  "bright-accent":
    "data:image/jpeg;base64,",
  "soft-lifestyle":
    "data:image/jpeg;base64,",
};
